import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"大壯","description":"高岛易断 - 大壯","frontmatter":{"title":"大壯","description":"高岛易断 - 大壯"},"headers":[],"relativePath":"zh/classics/takashima/034.md","filePath":"zh/classics/takashima/034.md"}'),i={name:"zh/classics/takashima/034.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="大壯" tabindex="-1">大壯 <a class="header-anchor" href="#大壯" aria-label="Permalink to “大壯”">​</a></h1><h2 id="大壯-1" tabindex="-1">大壯 <a class="header-anchor" href="#大壯-1" aria-label="Permalink to “大壯”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>大壮：利贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>阳为大，阳长至四，坚实而壮，故曰《大壮》。三阳为《泰》，至四而称壮，壮而曰大，壮之过也。《乾》曰“元亨利贞”，《震》曰“亨”，《大壮》不曰元亨，独曰“利贞”，而六爻又多戒辞，恐其失正而动，动必得咎，是知《大壮》非《易》之所贵也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>雷在天上，大壮，君子以非礼弗履。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>大象《震》雷，发于《乾》天，势力强壮，故名曰《大壮》。夫《随》、《复》、《豫》、《大壮》四卦，皆得《震》体，故皆取象于雷。《随》雷入泽中，阳势渐收，是谓秋雷；《复》雷入地中，阳势已微，是谓冬雷；《豫》“雷出地奋”，阳势方盛，是谓春雷；《大壮》曰“雷在天上”，阳势健盛，是谓当令之夏雷也。君子则之，谓雷之发声，必以其时，不时则为灾；君子之践履，必由于礼，非礼则有悔。《乾》为行，《震》为足，有《履》之象。《乾》之《象》曰，“君子以自强不息”，《震》之《象》曰，“君子以恐惧修省”，合而言之，君子因欲自强，惟以非礼而履者，为可惧耳，即夫子所谓“非礼勿视，非礼勿听，非礼勿言，非礼勿动”之旨也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问战征：军势强盛，有疾雷不及掩耳之势；但兵骄必败，所当深戒。</p><p>○　问营商：雷在天上，是货价高标之象，得价而售，不可过。</p><p>○　问功名：雷声远震，必得成名。</p><p>○　问家宅：防有火灾，宜祷。</p><p>○　问疾病：《震》为雷，亦为足，防有足疾，不能行也。</p><p>○　问婚姻：《震》为《乾》之长子，《巽》为《坤》之长女，是天合也，吉。</p><p>○　问失物：雷一过而无形，恐此物不能复得。</p><p>○　问六甲：生男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初居《大壮》之始，在下卦之下，在下而动，故曰“壮于趾”；《震》为征，故曰“征”；迈征而往，有急起直追之势，无“视履考祥”之念，是以凶也，故曰“征凶。”“有孚”，《象传》曰“其孚穷也”，谓初虽与四应，初既穷其所往，四又隔远，无能为力也，故曰“其孚穷也”。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问战征：“壮于趾，征凶”，为孤军深入者戒也，有勇无谋，是以凶也。</p><p>○　问营商：货财贩运，有不胫而走、不翼而飞之妙；然不度销路，而贸然而往，何能获利？故凶。</p><p>○　问功名：初本在下，曰“趾”，则动亦在下，功名必卑。</p><p>○　问家宅：“趾”，止也，此宅宜安止，不宜迁动，动则有凶。</p><p>○　问婚姻：防女有足疾。“征凶，有孚”，谓虽有聘约，“其孚穷也”。</p><p>○　问失物：此物已被足所践踏而坏。</p><p>○　问六甲：生男。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某来，请占事业之成否，筮得《大壮》之《恒》。</p><p>断曰：初爻居《乾》之始，在内卦之下，是必发事谋始，机会未至，而足先欲动者，故有壮趾之象。足下占事业，而得《大壮》初爻，知足下志在速成，当谋划未详，经验未定，而贸然前进，不特无利，且有凶也，故曰“壮于趾，征凶，有孚”。“壮于趾，征凶”者，谓轻举而取失败；“有孚”者，谓徒有此约信也。此事须待时而动，缓图则吉，今乃仓猝求成，是以凶也。友人不用此占，急遽兴业，遂致失策而倾家；后有人以资金三分之一，继承其业，反得大利。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>全卦诸爻，皆失于过刚，惟二爻为得中，中者不偏之谓也。二与五应，无抵触之失，是以无过不及，而进退适宜，故不言“壮”，不言“正”，直曰“贞吉”，盖即以《彖》之“利贞”归之，而著其吉也。《易》道虽贵扶阳抑阴，然阳刚过盛，亦失其中，故必抑其过刚，以就其中，中则正，正则吉也。《象传》曰“以中也”，以九二当下卦之中，刚而能柔，所处得中也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问战征：以中营得力，故能获胜，吉。</p><p>○　问营商：以货价适宜，得其时中，可获利也。</p><p>○　问功名：恰好中式，吉。</p><p>○　问婚姻：雀屏中选，吉。</p><p>○　问家宅：此宅坐西朝东，地位适中，大吉。</p><p>○　问疾病：病在中焦，宜用潜阳滋阴之剂，自得痊愈。吉。</p><p>○　问讼事：得中人调剂，即息。</p><p>○　问六甲：生男。</p><p>○　问行人：已在中途，即可归也。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某会社社长，来请占气运，筮得《大壮》之《丰》。</p><p>断曰：此卦四阳在下，二阴在上，阳大阴小，刚浸而长，故曰《大壮》。足下占会社而得二爻，可见社中资金充裕，足以有为。足下身任社长，所当以柔济刚，以静制动，从容办事，不期速效，谦和有礼，进退悉中，自能徐徐获益，吉无不利也。后二年，至四爻，四为《大壮》之主，可得大利。后果如所占。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“羝羊”，牡羊也。三至五体《兑》，为羊，故取象于羊；卦体纯刚，故曰“羝羊”，以喻刚阳之盛也。三当内卦之终，逼近外卦，《乾》刚《震》动，壮象将成。小人处此，必将恃其壮而壮焉，是谓“用壮”；君子有其壮，而不敢自居其壮，一若未尝有壮也，故曰“用罔”。“罔”，无也，京房曰，“壮一也，小人用之”，君子有而不用是也。三以阳处阳，重刚不中，虽贞亦危，故曰“贞厉”。君子因其厉而益加强焉，朝乾夕惕，时以非礼自防，不敢或逞其壮，所谓以有若无也。九四体《震》，为竹苇，故曰“藩”；藩所以闲羊，四在前，三触之，故曰“羝羊触藩”，象小人之用壮也。“羸”，郑虞作累，为拘累缠绕；“羸其角”，角，羊角，谓羊触藩，其角为藩所拘累，而不能出也，以喻用壮之危。“小人用壮”，当知所返矣；“君子用罔”，斯可免危矣。《象》曰“小人用壮”，小人第知有壮；“君子罔也”，去一“用”字，益见君子之不用，所贵敛之以无也。一说：罔，法网也，君子知壮之为厉，凛凛然以刑网为戒，即君子怀刑之意。亦通。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问战征：善战者审机察敌，不敢妄动；恃勇者逞强战斗，孤军直入，致陷险地而不能出，是以凶也。</p><p>○　问营商：自恃资财之富，任意垄断，一至货物毁折，无地销售，必遭大损。善贾者当无是虑。</p><p>○　问功名：鲁莽者必败，谦退者成名。</p><p>○　问家宅：此宅地位既高，建屋宜低，屋高恐有震陷之灾。</p><p>○　问疾病：病由血气过刚，药宜调血下气。</p><p>○　问讼事：以忍气受屈，息讼为宜，若健讼不休，讼则“终凶”。</p><p>○　问婚姻：两姓或一贫一富，若富者恃富凌贫，以致夫妻反目，凶。</p><p>○　问六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某来，请占商业盛衰，筮得《大壮》之《归妹》。</p><p>断曰：此卦内卦《乾》父，外卦《震》子，是父主谋于内，子干事于外，父子协力，以创兴家业，财力旺壮，故曰《大壮》。足下占商业，而得三爻，以阳居阳，爻位皆刚，若径情直往，其壮强之势，几可压倒同业，然过刚必折，恐反为同业所轧，必遭窘辱，如羊之触藩而不能出也。善贾者坚贞自处，不敢挟富而生骄，亦不敢恃才而自侈，虽有其壮，而不用其壮，斯得处壮之方，即得生财之道也。足下其熟审之！后友人乘壮用事，果为同业所挤，损失数万金。</p><p>明治二十七年五月中旬，我国驻英国公使某罹病，友人某忧之，请余一占。筮得《大壮》之《归妹》。</p><p>断曰：此卦阳长之卦，三爻又以阳居阳，《震》为木，木属肝，是必肝阳过盛，脾阴受克之症。某公使素体壮健，医者因其壮而误为实火，一味泻肝息阳，而元气愈虚，肝阳愈燥，病至不可药救，是谓用壮之误也。善医者当以育阴潜阳治之，所谓“用罔也”。至论爻象，三爻变为《归妹》，归者，归也，至四爻变《泰》，则病可疗。今当五月中旬，必过此一月后，可望平愈，然恐不及也。后某氏之病，果以翌月四日遂亡。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>九四出《乾》入《震》，为《震》之始，以阳居阴，不极其刚，故得吉而悔亡也。三之有藩，藩在四也，四前二阴，则藩决矣。“輹”，车轴缚也，《坤》为大舆，《震》上二阴得《坤》气，故亦曰“大舆”。輹壮则舆强，言行远而无碍也。率此以往，壮而不见其壮，悔何有焉？《象传》曰“藩决不羸，尚往也”，谓壮得其贞，乃可许其前往也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问战征：前途城垣已破，车驰马逐，长征可无阻也。</p><p>○　问功名：九四互《乾》，辰在戌，上值奎壁，壁主文昌，所以崇文德也，功名必显。王良五星在壁北，主车马，大舆之象；雷电六星亦相近，主兴雷，即《震》雷之象。</p><p>○　问营商：可许满载而归，吉。</p><p>○　问家宅：此宅当车马往来之地，宅前藩篱破落，急宜修整。</p><p>○　问疾病：人以发肤为藩卫，以心神为舆马，发肤破裂，心神摇荡，病不久矣。</p><p>○　问婚姻：“车脱輹，夫妻反目”，非佳偶也。不吉。</p><p>○　问六甲：九四为《震》之始，《震》一索得男，为长子也。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十七年九月，大本营之进广岛也，大元帅陛下，将发亲征。恭筮一卦，得《大壮》之《泰》。</p><p>断曰：此卦四阳连进，上决二阴，其势盛大，故曰《大壮》。今我兴征清之师，彼严兵固壁，尚不能当，况其藩卫已决，何能御我乎！恍如骋大车于坦途，可预决也。爻象如此，其吉可知，因呈此断于某贵显。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>上卦互《兑》，《兑》为羊，五正是羊。“丧”，亡也；“易”音亦，陆作场，谓疆场也，易场古通字。《乾》为郊，郊外谓之牧，五当《乾》郊外疆场之地，畜牧之所也。畜牧有藩，防其逸也。卦以《震》之下画为藩，三触之，四则藩决矣，五则羊逸，羊逸于易，所谓“大道多岐而亡羊”，故曰“丧羊于易”。五居《震》卦之中，偶画为阴，易，为旷郊阴地，阴爻而入阴地，不见其壮，故象为“丧羊”。且羊性刚卤，喜触，无羊则无触，无触则无用壮之悔，故曰“无悔”。《旅》上九曰“丧牛于易”，“易”亦作场。《旅》宜柔，丧其柔，是以“有凶”也；《大壮》恶刚，丧其刚，是以“无悔”也。《象传》曰：“位不当”，谓“无悔”在得中，不在当位，犹九二之“贞吉”，《象》曰“以中”，亦不在位也。总之，《大壮》一卦，《彖》所称“利贞”，以事理言，不以爻位言也，明矣。“易”字，郑谓交易，《本义》读作以智切，音异，谓容易也。义各有取。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问战征：三爻曰“羝羊触藩”，有攻击之象，“丧羊”则无触，而战事可平。</p><p>○　问营商：“易”，郑谓交易，有经商之义；“丧”，亡也，恐有小失，然无大悔。</p><p>○　问功名：以得为吉，以丧为凶，亡羊补牢，未为晚也。晚年可望。</p><p>○　问家宅：此宅在郊外空旷之处，于牧畜不利。</p><p>○　问疾病：“丧”，凶象，不吉。</p><p>○　问婚姻：牵羊担酒，婚礼也，无羊，婚礼不成。</p><p>○　问六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>友人某来曰：顷日有一种货物，可居奇获利，请占一卦，以定盈亏。筮得《大壮》之《夬》。</p><p>断曰：此卦四阳在下，其势甚壮，故名《大壮》。今占得第五爻，五处外卦之中，二画为阴，壮势已失，爻曰“丧羊”，是必有丧而无得。友人曰：台湾之事，购入军中所需食料品物，他日与清开战，实一大买卖也。后闻得和平之信，顿为惊愕，遂遭大耗，三年之后，犹不得偿全额云。</p><p>明治二十七年十一月二十日，某贵显来访曰：目下旅顺口形势如何？试为一筮。筮得《大壮》之《夬》。</p><p>断曰：以我国占旅顺，旅顺属清，是外国也。今占得五爻，五居外卦之中，当以我国为内卦，旅顺为外卦。“丧”者清国，得者我国也。爻辞“丧羊于易”，“易”，谓容易也。盖不须力战而得之也，数日内，当必有捷报到来。后数日，旅顺陷，果如此占。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上处外卦之终，与三相应，上之羊，犹是三之羊，上之触，犹是三之触。三虽羸角，乘刚而动，力能决藩，亦可进也，即不能进，尚可退也；至上势衰位极，爻处重阴，后路既断，前路又穷，将安归乎？不曰“不能进”，而曰“不能遂”，言终不能遂其壮往之愿也。视三之羸角，困益甚焉，利何有也！因退遂之不能，而惕之以“艰”，毖后惩前，“非礼弗履”，亦何难转咎为吉哉！《象传》所谓“不祥也”，言其不能“视履考祥”，故至退遂之两穷也。所谓“咎不长也”，言能知其所艰，则谨慎自守，壮终于此，咎亦终于此耳。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问战征：六处爻之穷，如追穷寇也，恃胜深入，及为败军所困，进退无路，凶道也。</p><p>○　问营商：是一意居奇，积货不售，至时过价贱，只要保本，而亦不得，其困甚矣。</p><p>○　问功名：在上爻有位高而危之象，若恋恋不退，一旦祸及，欲退不能，悔已晚矣。</p><p>○　问家宅：上爻居《震》之极，《震》为响，宅中必有响；《震》又为木，木动克土，恐有土精出现，土精为羊。其宅不利，所当艰难自守，至之卦为《晋》，《晋》曰“赐马蕃庶”，则可转咎为吉。</p><p>○　问婚姻：未及详探，一时已定，兹要改悔，必不能也。现当知苦困守，久后必佳。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>一日过访杉君，闲谈移晷，杉君谓余曰；昨夕有偷儿入我仓库，窃取物品若干，中有勋章礼服，是贵重之品也，未审可复得乎？子试筮之。筮得《大壮》之《晋》。</p><p>断曰：上为爻之极，贼窃得勋章礼服，贵重之品，在贼既不能转售，又不能自用，贼无所利，计亦穷矣。爻曰：“羝羊触藩”，羊性刚卤，以喻贼之卤莽也。“触藩”者贼，或将以此贵物，置之于邻近藩篱间乎？君请搜寻之。后果于邻邸墙垣上寻得之。杉君大为赞称。</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
